// ── Filter Messages ──────────────────────────────────────────────────────────
// Every message in the channel hits this node. Only real human messages get
// through. Returning [] halts the workflow, so nothing downstream costs money.
//
// The bot_id / SELF_BOT checks are the loop guard: this workflow REPLIES into
// the channel, and without them each reply would re-trigger the workflow and
// run away.

const SOURCE_CHANNEL = 'C0BS56L7V1A'; // #ops-team
const SELF_BOT = 'U0BSVQH51H6'; // Sysora Ops — never react to our own replies
const MIN_LENGTH = 8; // "ok", "thanks", ":+1:" are not requests

// n8n's Slack Trigger FLATTENS the event — it hands you {type,user,ts,text,
// channel,...} directly, not the raw {event:{...}} envelope the Slack API docs
// show. Accept either, so this works with the trigger and with a plain Webhook
// node fed the raw Slack body.
const raw = $input.first().json;
const ev = raw.event || raw;

if (ev.type !== 'message') return [];
if (ev.channel !== SOURCE_CHANNEL) return [];
if (ev.subtype) return []; // joins, edits, deletions, file shares
if (ev.bot_id) return []; // Jira integration, tldv, and our own posts
if (ev.user === SELF_BOT) return [];

const text = String(ev.text || '').trim();
if (text.length < MIN_LENGTH) return [];

// ── Idempotency guard ───────────────────────────────────────────────────────
// Slack redelivers events: it retries anything not acknowledged within 3s, and
// a duplicate subscription sends the same event twice. Either way the same
// client_msg_id arrives more than once, and without this each copy creates its
// own Jira ticket.
//
// Static data persists between executions of an ACTIVE workflow. Caveat worth
// knowing: n8n writes it when an execution ENDS, so two deliveries that run
// genuinely concurrently can both pass this check. It stops sequential
// redelivery, which is the common case; the real cure for concurrent copies is
// to stop them being sent (see README).
const store = $getWorkflowStaticData('global');
store.seen = Array.isArray(store.seen) ? store.seen : [];

const msgId = ev.client_msg_id || ev.event_ts || ev.ts;
if (store.seen.includes(msgId)) return [];

store.seen.push(msgId);
if (store.seen.length > 300) store.seen = store.seen.slice(-300);

return [
  {
    json: {
      text,
      user: ev.user,
      channel: ev.channel,
      ts: ev.ts,
      // Reply into the thread of the original message. If the client wrote in
      // an existing thread, stay in that thread instead of starting a new one.
      threadTs: ev.thread_ts || ev.ts,
    },
  },
];

// ── Parse Intent ─────────────────────────────────────────────────────────────
// Turns the model's reply into a trusted, well-formed object and builds the JQL.
//
// The model's output is treated as untrusted text throughout: the intent is
// whitelisted, the issue key must match the real key format, and the search
// terms are stripped of every character that has meaning in JQL. Without that
// last step a client could write a message that breaks out of the quoted string
// and rewrites the query.

const PROJECT = 'GS';
const VALID_INTENTS = ['new_task', 'status_request', 'other'];
const VALID_PRIORITIES = ['Highest', 'High', 'Medium', 'Low', 'Lowest'];

// Jira numeric IDs for the GiveSuite project (id 10002). The Jira API takes
// IDs, not names, and these are stable per project.
const ISSUE_TYPE_IDS = { Bug: '10015', Task: '10012', Story: '10013', Feature: '10014' };
const DEFAULT_ISSUE_TYPE = 'Task';

const ctx = $('Filter Messages').first().json;
const modelText = String($input.first().json.text || $input.first().json.output || '');

let ai = {};
try {
  const m = modelText.match(/\{[\s\S]*\}/);
  if (m) ai = JSON.parse(m[0]);
} catch (e) {
  // leave ai empty; defaults below take over
}

const intent = VALID_INTENTS.includes(ai.intent) ? ai.intent : 'other';
const priority = VALID_PRIORITIES.includes(ai.priority) ? ai.priority : 'Medium';
const issueType = Object.prototype.hasOwnProperty.call(ISSUE_TYPE_IDS, ai.issueType)
  ? ai.issueType
  : DEFAULT_ISSUE_TYPE;

// Only accept a key that looks like a real key for THIS project.
const keyRe = new RegExp('^' + PROJECT + '-\\d+$');
const issueKey = typeof ai.issueKey === 'string' && keyRe.test(ai.issueKey.trim())
  ? ai.issueKey.trim()
  : null;

// JQL-safe: keep letters, digits, spaces and hyphens. Nothing else survives.
const terms = String(ai.searchTerms || ctx.text)
  .replace(/[^A-Za-z0-9 -]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .split(' ')
  .filter((w) => w.length > 2)
  .slice(0, 8)
  .join(' ');

let jql;
if (issueKey) {
  jql = 'key = ' + issueKey;
} else if (terms) {
  jql = 'project = ' + PROJECT + ' AND text ~ "' + terms + '" ORDER BY updated DESC';
} else {
  jql = 'project = ' + PROJECT + ' AND created >= -1d ORDER BY updated DESC';
}

const title = String(ai.title || ctx.text).replace(/\s+/g, ' ').trim().slice(0, 120);
const description = String(ai.description || ctx.text).trim();

return [
  {
    json: {
      ...ctx,
      intent,
      issueKey,
      issueType,
      issueTypeId: ISSUE_TYPE_IDS[issueType],
      priority,
      terms,
      jql,
      title,
      description,
      aiRaw: modelText.slice(0, 500),
    },
  },
];

// ── Decide Action ────────────────────────────────────────────────────────────
// Reads the Jira search results and decides the single next move. Formatting
// now lives downstream: the create path builds its own message, and the status
// path needs the ticket's comments first, so this node only decides and
// normalises the matched issue.
//
// Search runs for BOTH intents on purpose. For a status request it finds the
// task to report on; for a new request it catches the case where the client is
// re-reporting something already logged, so we link the existing ticket
// instead of creating a duplicate.

const ctx = $('Parse Intent').first().json;

// Jira "getAll" with alwaysOutputData emits one empty item when nothing matches.
const hits = $input
  .all()
  .map((i) => i.json)
  .filter((j) => j && typeof j.key === 'string' && j.key);

const hit = hits[0] || null;

if (ctx.intent === 'other') {
  // Nothing actionable was said. Stay quiet rather than reply with noise.
  return [];
}

let matched = null;
if (hit) {
  const f = hit.fields || {};
  matched = {
    key: hit.key,
    summary: f.summary || '',
    status: (f.status && f.status.name) || 'Unknown',
    assignee: (f.assignee && f.assignee.displayName) || 'Unassigned',
    priority: (f.priority && f.priority.name) || '',
    duedate: f.duedate || '',
    updated: f.updated || '',
  };
}

return [
  {
    json: {
      ...ctx,
      shouldCreate: !matched,
      matched,
      matchedKey: matched ? matched.key : null,
      // A new report that collided with an existing ticket. The status reply
      // adds a line explaining why nothing new was raised.
      isDuplicateReport: Boolean(matched) && ctx.intent === 'new_task',
      hitCount: hits.length,
    },
  },
];

// ── Status Reply ─────────────────────────────────────────────────────────────
// Builds the "here is where your task stands" message: the live Jira fields
// plus the most recent comments.
//
// WHAT GETS SHOWN. Jira comments are written for the team, not the client.
// Two filters guard against leaking internal discussion into a channel a
// client can read:
//   1. Any comment with a Jira visibility restriction (role/group limited) is
//      always dropped — Jira already marked it as not-for-everyone.
//   2. CLIENT_SAFE_MARKER, when set, shows ONLY comments containing that
//      marker. Turn it on if this channel ever has clients in it, and have the
//      team prefix updates they are happy to share.

const BASE = 'https://sysorastack.atlassian.net/browse/';
const MAX_COMMENTS = 3;
const MAX_COMMENT_CHARS = 400;
const CLIENT_SAFE_MARKER = ''; // e.g. '[client]' to show only marked comments

const ctx = $('Decide Action').first().json;
const m = ctx.matched || {};

// Jira Cloud returns comment bodies as Atlassian Document Format (nested JSON),
// not a string, unless the node simplified them. Handle both.
function adfToText(body) {
  if (!body) return '';
  if (typeof body === 'string') return body;
  const parts = [];
  const walk = (n) => {
    if (!n) return;
    if (Array.isArray(n)) return n.forEach(walk);
    if (n.type === 'text' && n.text) parts.push(n.text);
    if (n.type === 'hardBreak') parts.push('\n');
    if (n.content) walk(n.content);
  };
  walk(body.content || body);
  return parts.join('').replace(/\n{3,}/g, '\n\n').trim();
}

const raw = $input
  .all()
  .map((i) => i.json)
  .filter((c) => c && (c.id || c.body));

const comments = raw
  .filter((c) => !c.visibility) // Jira-restricted: never surface
  .map((c) => ({
    author: (c.author && (c.author.displayName || c.author.name)) || 'Someone',
    when: (c.created || '').slice(0, 10),
    text: adfToText(c.body),
  }))
  .filter((c) => c.text)
  .filter((c) => !CLIENT_SAFE_MARKER || c.text.includes(CLIENT_SAFE_MARKER))
  .slice(-MAX_COMMENTS);

const lines = [];
lines.push('*<' + BASE + m.key + '|' + m.key + '> — ' + (m.summary || '') + '*');

const facts = [
  m.status ? '*Status:* ' + m.status : null,
  m.priority ? '*Priority:* ' + m.priority : null,
  m.assignee ? '*Assignee:* ' + m.assignee : null,
  m.duedate ? '*Due:* ' + m.duedate : null,
].filter(Boolean);
if (facts.length) lines.push(facts.join('   '));
if (m.updated) lines.push('_Last updated ' + String(m.updated).slice(0, 10) + '_');

if (comments.length) {
  lines.push('');
  lines.push(comments.length === 1 ? '*Latest update:*' : '*Latest updates:*');
  for (const c of comments) {
    let t = c.text.replace(CLIENT_SAFE_MARKER, '').trim();
    if (t.length > MAX_COMMENT_CHARS) t = t.slice(0, MAX_COMMENT_CHARS) + '…';
    lines.push('> *' + c.author + '* (' + c.when + '): ' + t.split('\n').join(' '));
  }
} else {
  lines.push('');
  lines.push('_No notes on the ticket yet — the team will post updates here as it moves._');
}

if (ctx.isDuplicateReport) {
  lines.push('');
  lines.push(
    'This looked like something already logged, so I have not raised a duplicate. ' +
      'If it is actually a different issue, say so and I will create a separate ticket.'
  );
}

return [{ json: { ...ctx, reply: lines.join('\n'), commentCount: comments.length } }];

// ── Created Reply ────────────────────────────────────────────────────────────
// Runs after the Jira issue is created. Builds the confirmation that goes back
// into the client's own thread.

const BASE = 'https://sysorastack.atlassian.net/browse/';

const ctx = $('Decide Action').first().json;
const created = $input.first().json || {};
const key = created.key || null;

if (!key) {
  // Jira accepted the call but gave us no key — tell the truth rather than
  // claiming a ticket exists.
  return [
    {
      json: {
        ...ctx,
        reply:
          'I tried to log this but Jira did not return a ticket reference. ' +
          'Flagging it for the Ops team to raise manually.',
      },
    },
  ];
}

const reply =
  'Logged as <' + BASE + key + '|' + key + '> — *' + ctx.title + '*\n' +
  'This has gone to the Ops team at Sysora Stack for review. ' +
  'They will pick it up and you will be notified in this thread as it progresses.';

return [{ json: { ...ctx, reply, createdKey: key } }];
